window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b7bb63b523dc3dc1"]={"versions": [{"id": "FIG-b7bb63b523dc3dc1", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Sequence Diagram) gemäß AUTOSAR-Modellierungsstandard.\n</li><li><strong>Architektur-Ebene:</strong> AUTOSAR Classic Platform (R4.0.3), System Services Layer (BSW).\n</li><li><strong>Funktionaler Zweck:</strong> Spezifikation des Kontrollflusses auf einem Slave-Core während der Phase <code>OffPostOS</code> des ECU State Manager (<code>EcuM</code>). Es definiert das deterministische Minimalverhalten von Sekundärkernen nach der Beendigung des Betriebssystems (<code>ShutdownOS</code>), um eine unkoordinierte Deinitialisierung von BSW-Ressourcen gegenüber dem Master-Core zu unterbinden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Module &amp; Lebenslinien:</strong>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: Instanz des ECU State Managers auf dem jeweiligen Slave-Core. Enthält das UML-Dekompositions-/Referenzsymbol (zwei horizontal verbundene Ovale) als Verweis auf Sub-Zustände bzw. ausgelagerte Core-Handling-Routinen.\n</li><li><code>«module» McOs</code>: Multi-Core Operating System (AUTOSAR OS / BSW-Treiberklasse für Core-Management).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>GetCoreID(CoreIdType)</code>: Synchrone Abfrage von <code>EcuM</code> an <code>McOs</code>. Entspricht normativ der AUTOSAR-OS-API <code>CoreIdType GetCoreID(void)</code> zur Ermittlung des logischen Core-Identifikators des aktuell ausführenden Prozessorkerns.\n</li></ul>\n</li><li><strong>Strukturelle Beziehungen:</strong> Asymmetrisches Multi-Core-Paradigma; der Slave-Core besitzt keine Koppelung zu Hardware-Deinitialisierern (<code>Mcu</code>, <code>Gpt</code>, etc.) in dieser Phase.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Eintritt des Slave-Cores in die <code>OffPostOS</code>-Phase nach erfolgtem OS-Shutdown (<code>ShutdownOS()</code> bzw. Abschluss der Shutdown-Hooks).\n</li><li><strong>Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>EcuM</code> setzt auf dem Slave-Core die synchrone Service-Anfrage <code>GetCoreID()</code> an das <code>McOs</code> ab.\n</li><li><code>McOs</code> ermittelt hardwarenah die Core-Identität und liefert den Wert vom Typ <code>CoreIdType</code> über den Rückgabepfad (gestrichelte Linie mit offener Pfeilspitze) an <code>EcuM</code> zurück.\n</li><li>Die EcuM-Lebenslinie terminiert ohne Folgeaufrufe an BSW-Treiber. Der Slave-Core verharrt im Haltezustand (z. B. Idle-Loop / CPU-Halt / <code>WFI</code>/<code>WFE</code>-Befehl), bis der Master-Core die Gesamt-MCU abschaltet, schlafen legt oder zurücksetzt.\n</li></ol>\n</li><li><strong>Fehlerbehandlung / Callbacks:</strong> Keine Fehlerpfade, Dem-/Det-Meldungen oder asynchronen Verzweigungen vorgesehen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Asymmetrischer Shutdown-Vertrag:</strong> Treiber-Deinitialisierungen (<code>&lt;Driver&gt;_DeInit</code>), Sleep-Mode-Setzungen (<code>Mcu_SetMode</code>) und System-Resets (<code>Mcu_PerformReset</code>) sind im AUTOSAR-Standard exklusiv dem Master-Core vorbehalten. Slave-Cores dürfen in <code>OffPostOS</code> keinerlei periphere Register mehr manipulieren.\n</li><li><strong>OS-Reentrancy im Post-OS-Zustand:</strong> Die OS-Funktion <code>GetCoreID()</code> muss zwingend so implementiert sein, dass sie auch nach heruntergefahrenem OS-Scheduler (inaktive Task-/ISR-Verwaltung) aufrufbar bleibt. Sie muss direkt auf ein prozessoreigenes Core-ID-Register zugreifen und darf keine OS-internen Schutzmechanismen (Spinlocks, Scheduler-Sperren) erfordern.\n</li><li><strong>Synchronisationsanforderung für Plattform-Entwickler:</strong> Der Master-Core muss vor der Ausführung des finalen MCU-Resets oder Power-Offs über Hardware-Register (z. B. Semaphoren / Inter-Core-Flags) sicherstellen, dass alle Slave-Cores diesen Post-OS-Haltezustand erreicht haben, um unvollständige Buszugriffe oder Speicher-Inkonsistenzen zu vermeiden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3a37bcd6b0f9e796", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Sequence Diagram) gemäß AUTOSAR-Modellierungsstandard.\n</li><li><strong>Architektur-Ebene:</strong> AUTOSAR Classic Platform (R4.0.3), System Services Layer (BSW).\n</li><li><strong>Funktionaler Zweck:</strong> Spezifikation des Kontrollflusses auf einem Slave-Core während der Phase <code>OffPostOS</code> des ECU State Manager (<code>EcuM</code>). Es definiert das deterministische Minimalverhalten von Sekundärkernen nach der Beendigung des Betriebssystems (<code>ShutdownOS</code>), um eine unkoordinierte Deinitialisierung von BSW-Ressourcen gegenüber dem Master-Core zu unterbinden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Module &amp; Lebenslinien:</strong>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: Instanz des ECU State Managers auf dem jeweiligen Slave-Core mit UML-Dekompositionssymbol (zwei horizontal verbundene Ovale).\n</li><li><code>Integration Code</code>: Integrator-spezifische Code-Ebene bzw. Callout-Schicht außerhalb der standardisierten BSW-Module zur Ausführung hardwarenaher Anpassungen.\n</li><li><code>«module» McOs</code>: Multi-Core Operating System (AUTOSAR OS / BSW-Treiberklasse für Core-Management).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>GetCoreID(CoreIdType)</code>: Synchrone Service-Abfrage von <code>EcuM</code> an <code>McOs</code>. Entspricht der OS-API <code>CoreIdType GetCoreID(void)</code> zur Bestimmung der logischen Core-ID des ausführenden Slave-Kerns.\n</li><li><code>EcuM_OnGoOffTwo()</code>: Synchroner Callout-Aufruf von <code>EcuM</code> an den <code>Integration Code</code> ohne Übergabeparameter und Rückgabewert (<code>void EcuM_OnGoOffTwo(void)</code>).\n</li></ul>\n</li><li><strong>Strukturelle Beziehungen:</strong> Asymmetrisches Multi-Core-Konzept; <code>EcuM</code> interagiert auf dem Slave-Core in dieser Phase ausschließlich mit dem Betriebssystem (<code>McOs</code>) und dem <code>Integration Code</code>, ohne direkte Kopplung an BSW-Treiber (<code>Mcu</code>, <code>Gpt</code> etc.).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Eintritt des Slave-Cores in die <code>OffPostOS</code>-Phase nach erfolgtem OS-Shutdown (<code>ShutdownOS()</code> bzw. Abarbeitung der Shutdown-Hooks).\n</li><li><strong>Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>EcuM</code> setzt auf dem Slave-Core die synchrone Service-Anfrage <code>GetCoreID()</code> an <code>McOs</code> ab.\n</li><li><code>McOs</code> liefert den Identifikator vom Typ <code>CoreIdType</code> über den Rückgabepfad an <code>EcuM</code> zurück.\n</li><li><code>EcuM</code> ruft synchron den Integrations-Hook <code>EcuM_OnGoOffTwo()</code> im <code>Integration Code</code> auf.\n</li><li>Nach Rückkehr aus <code>EcuM_OnGoOffTwo()</code> endet der Kontrollfluss von <code>EcuM</code> auf dem Slave-Core. Der Kern verharrt im Haltezustand (z. B. Idle-Schleife, Low-Power-Wartemodus wie <code>WFI</code>/<code>WFE</code>), bis der Master-Core die Gesamt-MCU abschaltet oder zurücksetzt.\n</li></ol>\n</li><li><strong>Fehlerbehandlung / Callbacks:</strong> Keine Fehlerbehandlungspfade, Verzweigungen oder Statusrückmeldungen dargestellt.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Asymmetrischer Shutdown-Vertrag:</strong> Treiber-Deinitialisierungen (<code>&lt;Driver&gt;_DeInit</code>), Sleep-Mode-Setzungen (<code>Mcu_SetMode</code>) und System-Resets (<code>Mcu_PerformReset</code>) sind im AUTOSAR-Standard exklusiv dem Master-Core vorbehalten. Slave-Cores manipulieren in <code>OffPostOS</code> keine geteilten Peripherieregister.\n</li><li><strong>Rolle von <code>EcuM_OnGoOffTwo()</code>:</strong> Die Callout-Funktion erlaubt systemspezifische Nachbereitungen auf dem jeweiligen Slave-Core unmittelbar vor dem endgültigen Stillstand (z. B. lokales Abschalten von Core-Clocks, Power-Downs oder Übergang in spezifische Halteinstruktionen). Da das Betriebssystem bereits heruntergefahren ist, dürfen in <code>EcuM_OnGoOffTwo()</code> keine blockierenden OS-Dienste oder Scheduler-abhängigen BSW-APIs aufgerufen werden.\n</li><li><strong>OS-Reentrancy im Post-OS-Zustand:</strong> Die OS-Funktion <code>GetCoreID()</code> muss auch nach inaktivem OS-Scheduler direkt auf prozessoreigene Core-Register zugreifen können, ohne auf Spinlocks oder OS-Verwaltungsstrukturen angewiesen zu sein.\n</li><li><strong>Synchronisationsanforderung für Plattform-Entwickler:</strong> Der Master-Core muss sicherstellen (z. B. über Hardware-Flags oder Inter-Core-Kommunikation), dass alle Slave-Cores <code>EcuM_OnGoOffTwo()</code> abgeschlossen haben und im sicheren Ruhezustand verharren, bevor die Gesamt-MCU stromlos geschaltet oder zurückgesetzt wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-df6d1d779eb7b0f7", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Sequence Diagram) gemäß AUTOSAR-Modellierungsstandard.\n</li><li><strong>Architektur-Ebene:</strong> AUTOSAR Classic Platform (R4.0.3), System Services Layer (BSW).\n</li><li><strong>Funktionaler Zweck:</strong> Spezifikation des Kontrollflusses auf einem Slave-Core während der Phase <code>OffPostOS</code> des ECU State Manager (<code>EcuM</code>). Es definiert das deterministische Minimalverhalten von Sekundärkernen nach der Beendigung des Betriebssystems (<code>ShutdownOS</code>), um eine unkoordinierte Deinitialisierung von BSW-Ressourcen gegenüber dem Master-Core zu unterbinden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Module &amp; Lebenslinien:</strong>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: Instanz des ECU State Managers auf dem jeweiligen Slave-Core mit UML-Dekompositionssymbol (zwei horizontal verbundene Ovale).\n</li><li><code>Integration Code</code>: Integrator-spezifische Code-Ebene bzw. Callout-Schicht außerhalb der standardisierten BSW-Module zur Ausführung hardwarenaher Anpassungen.\n</li><li><code>«module» McOs</code>: Multi-Core Operating System (AUTOSAR OS / BSW-Treiberklasse für Core-Management).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>GetCoreID(CoreIdType)</code>: Synchrone Service-Abfrage von <code>EcuM</code> an <code>McOs</code>. Entspricht der OS-API <code>CoreIdType GetCoreID(void)</code> zur Bestimmung der logischen Core-ID des ausführenden Slave-Kerns.\n</li><li><code>EcuM_OnGoOffTwo()</code>: Synchroner Callout-Aufruf von <code>EcuM</code> an den <code>Integration Code</code> ohne Übergabeparameter und Rückgabewert (<code>void EcuM_OnGoOffTwo(void)</code>).\n</li></ul>\n</li><li><strong>Strukturelle Beziehungen:</strong> Asymmetrisches Multi-Core-Konzept; <code>EcuM</code> interagiert auf dem Slave-Core in dieser Phase ausschließlich mit dem Betriebssystem (<code>McOs</code>) und dem <code>Integration Code</code>, ohne direkte Kopplung an BSW-Treiber (<code>Mcu</code>, <code>Gpt</code> etc.).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Eintritt des Slave-Cores in die <code>OffPostOS</code>-Phase nach erfolgtem OS-Shutdown (<code>ShutdownOS()</code> bzw. Abarbeitung der Shutdown-Hooks).\n</li><li><strong>Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>EcuM</code> setzt auf dem Slave-Core die synchrone Service-Anfrage <code>GetCoreID()</code> an <code>McOs</code> ab.\n</li><li><code>McOs</code> liefert den Identifikator vom Typ <code>CoreIdType</code> über den Rückgabepfad an <code>EcuM</code> zurück.\n</li><li><code>EcuM</code> ruft synchron den Integrations-Hook <code>EcuM_OnGoOffTwo()</code> im <code>Integration Code</code> auf.\n</li><li>Nach Rückkehr aus <code>EcuM_OnGoOffTwo()</code> endet der Kontrollfluss von <code>EcuM</code> auf dem Slave-Core. Der Kern verharrt im Haltezustand (z. B. Idle-Schleife, Low-Power-Wartemodus wie <code>WFI</code>/<code>WFE</code>), bis der Master-Core die Gesamt-MCU abschaltet oder zurücksetzt.\n</li></ol>\n</li><li><strong>Fehlerbehandlung / Callbacks:</strong> Keine Fehlerbehandlungspfade, Verzweigungen oder Statusrückmeldungen dargestellt.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Asymmetrischer Shutdown-Vertrag:</strong> Treiber-Deinitialisierungen (<code>&lt;Driver&gt;_DeInit</code>), Sleep-Mode-Setzungen (<code>Mcu_SetMode</code>) und System-Resets (<code>Mcu_PerformReset</code>) sind im AUTOSAR-Standard exklusiv dem Master-Core vorbehalten. Slave-Cores manipulieren in <code>OffPostOS</code> keine geteilten Peripherieregister.\n</li><li><strong>Rolle von <code>EcuM_OnGoOffTwo()</code>:</strong> Die Callout-Funktion erlaubt systemspezifische Nachbereitungen auf dem jeweiligen Slave-Core unmittelbar vor dem endgültigen Stillstand (z. B. lokales Abschalten von Core-Clocks, Power-Downs oder Übergang in spezifische Halteinstruktionen). Da das Betriebssystem bereits heruntergefahren ist, dürfen in <code>EcuM_OnGoOffTwo()</code> keine blockierenden OS-Dienste oder Scheduler-abhängigen BSW-APIs aufgerufen werden.\n</li><li><strong>OS-Reentrancy im Post-OS-Zustand:</strong> Die OS-Funktion <code>GetCoreID()</code> muss auch nach inaktivem OS-Scheduler direkt auf prozessoreigene Core-Register zugreifen können, ohne auf Spinlocks oder OS-Verwaltungsstrukturen angewiesen zu sein.\n</li><li><strong>Synchronisationsanforderung für Plattform-Entwickler:</strong> Der Master-Core muss sicherstellen (z. B. über Hardware-Flags oder Inter-Core-Kommunikation), dass alle Slave-Cores <code>EcuM_OnGoOffTwo()</code> abgeschlossen haben und im sicheren Ruhezustand verharren, bevor die Gesamt-MCU stromlos geschaltet oder zurückgesetzt wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cd3d8767072fc514", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Sequence Diagram) gemäß AUTOSAR-Modellierungsstandard.\n</li><li><strong>Architektur-Ebene:</strong> AUTOSAR Classic Platform (R4.0.3), System Services Layer (BSW).\n</li><li><strong>Funktionaler Zweck:</strong> Spezifikation des Kontrollflusses auf einem Slave-Core während der Phase <code>OffPostOS</code> des ECU State Manager (<code>EcuM</code>). Es definiert das deterministische Minimalverhalten von Sekundärkernen nach der Beendigung des Betriebssystems (<code>ShutdownOS</code>), um eine unkoordinierte Deinitialisierung von BSW-Ressourcen gegenüber dem Master-Core zu unterbinden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Module &amp; Lebenslinien:</strong>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: Instanz des ECU State Managers auf dem jeweiligen Slave-Core mit UML-Dekompositionssymbol (zwei horizontal verbundene Ovale).\n</li><li><code>Integration Code</code>: Integrator-spezifische Code-Ebene bzw. Callout-Schicht außerhalb der standardisierten BSW-Module zur Ausführung hardwarenaher Anpassungen.\n</li><li><code>«module» McOs</code>: Multi-Core Operating System (AUTOSAR OS / BSW-Treiberklasse für Core-Management).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>GetCoreID(CoreIdType)</code>: Synchrone Service-Abfrage von <code>EcuM</code> an <code>McOs</code>. Entspricht der OS-API <code>CoreIdType GetCoreID(void)</code> zur Bestimmung der logischen Core-ID des ausführenden Slave-Kerns.\n</li><li><code>EcuM_OnGoOffTwo()</code>: Synchroner Callout-Aufruf von <code>EcuM</code> an den <code>Integration Code</code> ohne Übergabeparameter und Rückgabewert (<code>void EcuM_OnGoOffTwo(void)</code>).\n</li></ul>\n</li><li><strong>Strukturelle Beziehungen:</strong> Asymmetrisches Multi-Core-Konzept; <code>EcuM</code> interagiert auf dem Slave-Core in dieser Phase ausschließlich mit dem Betriebssystem (<code>McOs</code>) und dem <code>Integration Code</code>, ohne direkte Kopplung an BSW-Treiber (<code>Mcu</code>, <code>Gpt</code> etc.).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Eintritt des Slave-Cores in die <code>OffPostOS</code>-Phase nach erfolgtem OS-Shutdown (<code>ShutdownOS()</code> bzw. Abarbeitung der Shutdown-Hooks).\n</li><li><strong>Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>EcuM</code> setzt auf dem Slave-Core die synchrone Service-Anfrage <code>GetCoreID()</code> an <code>McOs</code> ab.\n</li><li><code>McOs</code> liefert den Identifikator vom Typ <code>CoreIdType</code> über den Rückgabepfad an <code>EcuM</code> zurück.\n</li><li><code>EcuM</code> ruft synchron den Integrations-Hook <code>EcuM_OnGoOffTwo()</code> im <code>Integration Code</code> auf.\n</li><li>Nach Rückkehr aus <code>EcuM_OnGoOffTwo()</code> endet der Kontrollfluss von <code>EcuM</code> auf dem Slave-Core. Der Kern verharrt im Haltezustand (z. B. Idle-Schleife, Low-Power-Wartemodus wie <code>WFI</code>/<code>WFE</code>), bis der Master-Core die Gesamt-MCU abschaltet oder zurücksetzt.\n</li></ol>\n</li><li><strong>Fehlerbehandlung / Callbacks:</strong> Keine Fehlerbehandlungspfade, Verzweigungen oder Statusrückmeldungen dargestellt.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Asymmetrischer Shutdown-Vertrag:</strong> Treiber-Deinitialisierungen (<code>&lt;Driver&gt;_DeInit</code>), Sleep-Mode-Setzungen (<code>Mcu_SetMode</code>) und System-Resets (<code>Mcu_PerformReset</code>) sind im AUTOSAR-Standard exklusiv dem Master-Core vorbehalten. Slave-Cores manipulieren in <code>OffPostOS</code> keine geteilten Peripherieregister.\n</li><li><strong>Rolle von <code>EcuM_OnGoOffTwo()</code>:</strong> Die Callout-Funktion erlaubt systemspezifische Nachbereitungen auf dem jeweiligen Slave-Core unmittelbar vor dem endgültigen Stillstand (z. B. lokales Abschalten von Core-Clocks, Power-Downs oder Übergang in spezifische Halteinstruktionen). Da das Betriebssystem bereits heruntergefahren ist, dürfen in <code>EcuM_OnGoOffTwo()</code> keine blockierenden OS-Dienste oder Scheduler-abhängigen BSW-APIs aufgerufen werden.\n</li><li><strong>OS-Reentrancy im Post-OS-Zustand:</strong> Die OS-Funktion <code>GetCoreID()</code> muss auch nach inaktivem OS-Scheduler direkt auf prozessoreigene Core-Register zugreifen können, ohne auf Spinlocks oder OS-Verwaltungsstrukturen angewiesen zu sein.\n</li><li><strong>Synchronisationsanforderung für Plattform-Entwickler:</strong> Der Master-Core muss sicherstellen (z. B. über Hardware-Flags oder Inter-Core-Kommunikation), dass alle Slave-Cores <code>EcuM_OnGoOffTwo()</code> abgeschlossen haben und im sicheren Ruhezustand verharren, bevor die Gesamt-MCU stromlos geschaltet oder zurückgesetzt wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e1989153673aaaf6", "releases": ["R20-11", "R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Sequence Diagram) gemäß AUTOSAR-Modellierungsstandard.\n</li><li><strong>Architektur-Ebene:</strong> AUTOSAR Classic Platform (R4.0.3), System Services Layer (BSW).\n</li><li><strong>Funktionaler Zweck:</strong> Spezifikation des Kontrollflusses auf einem Slave-Core während der Phase <code>OffPostOS</code> des ECU State Manager (<code>EcuM</code>). Es definiert das deterministische Minimalverhalten von Sekundärkernen nach der Beendigung des Betriebssystems (<code>ShutdownOS</code>), um eine unkoordinierte Deinitialisierung von BSW-Ressourcen gegenüber dem Master-Core zu unterbinden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Module &amp; Lebenslinien:</strong>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: Instanz des ECU State Managers auf dem jeweiligen Slave-Core mit UML-Dekompositionssymbol (zwei horizontal verbundene Ovale).\n</li><li><code>Integration Code</code>: Integrator-spezifische Code-Ebene bzw. Callout-Schicht außerhalb der standardisierten BSW-Module zur Ausführung hardwarenaher Anpassungen.\n</li><li><code>«module» McOs</code>: Multi-Core Operating System (AUTOSAR OS / BSW-Treiberklasse für Core-Management).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>GetCoreID(CoreIdType)</code>: Synchrone Service-Abfrage von <code>EcuM</code> an <code>McOs</code>. Entspricht der OS-API <code>CoreIdType GetCoreID(void)</code> zur Bestimmung der logischen Core-ID des ausführenden Slave-Kerns.\n</li><li><code>EcuM_OnGoOffTwo()</code>: Synchroner Callout-Aufruf von <code>EcuM</code> an den <code>Integration Code</code> ohne Übergabeparameter und Rückgabewert (<code>void EcuM_OnGoOffTwo(void)</code>).\n</li></ul>\n</li><li><strong>Strukturelle Beziehungen:</strong> Asymmetrisches Multi-Core-Konzept; <code>EcuM</code> interagiert auf dem Slave-Core in dieser Phase ausschließlich mit dem Betriebssystem (<code>McOs</code>) und dem <code>Integration Code</code>, ohne direkte Kopplung an BSW-Treiber (<code>Mcu</code>, <code>Gpt</code> etc.).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Eintritt des Slave-Cores in die <code>OffPostOS</code>-Phase nach erfolgtem OS-Shutdown (<code>ShutdownOS()</code> bzw. Abarbeitung der Shutdown-Hooks).\n</li><li><strong>Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>EcuM</code> setzt auf dem Slave-Core die synchrone Service-Anfrage <code>GetCoreID()</code> an <code>McOs</code> ab.\n</li><li><code>McOs</code> liefert den Identifikator vom Typ <code>CoreIdType</code> über den Rückgabepfad an <code>EcuM</code> zurück.\n</li><li><code>EcuM</code> ruft synchron den Integrations-Hook <code>EcuM_OnGoOffTwo()</code> im <code>Integration Code</code> auf.\n</li><li>Nach Rückkehr aus <code>EcuM_OnGoOffTwo()</code> endet der Kontrollfluss von <code>EcuM</code> auf dem Slave-Core. Der Kern verharrt im Haltezustand (z. B. Idle-Schleife, Low-Power-Wartemodus wie <code>WFI</code>/<code>WFE</code>), bis der Master-Core die Gesamt-MCU abschaltet oder zurücksetzt.\n</li></ol>\n</li><li><strong>Fehlerbehandlung / Callbacks:</strong> Keine Fehlerbehandlungspfade, Verzweigungen oder Statusrückmeldungen dargestellt.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Asymmetrischer Shutdown-Vertrag:</strong> Treiber-Deinitialisierungen (<code>&lt;Driver&gt;_DeInit</code>), Sleep-Mode-Setzungen (<code>Mcu_SetMode</code>) und System-Resets (<code>Mcu_PerformReset</code>) sind im AUTOSAR-Standard exklusiv dem Master-Core vorbehalten. Slave-Cores manipulieren in <code>OffPostOS</code> keine geteilten Peripherieregister.\n</li><li><strong>Rolle von <code>EcuM_OnGoOffTwo()</code>:</strong> Die Callout-Funktion erlaubt systemspezifische Nachbereitungen auf dem jeweiligen Slave-Core unmittelbar vor dem endgültigen Stillstand (z. B. lokales Abschalten von Core-Clocks, Power-Downs oder Übergang in spezifische Halteinstruktionen). Da das Betriebssystem bereits heruntergefahren ist, dürfen in <code>EcuM_OnGoOffTwo()</code> keine blockierenden OS-Dienste oder Scheduler-abhängigen BSW-APIs aufgerufen werden.\n</li><li><strong>OS-Reentrancy im Post-OS-Zustand:</strong> Die OS-Funktion <code>GetCoreID()</code> muss auch nach inaktivem OS-Scheduler direkt auf prozessoreigene Core-Register zugreifen können, ohne auf Spinlocks oder OS-Verwaltungsstrukturen angewiesen zu sein.\n</li><li><strong>Synchronisationsanforderung für Plattform-Entwickler:</strong> Der Master-Core muss sicherstellen (z. B. über Hardware-Flags oder Inter-Core-Kommunikation), dass alle Slave-Cores <code>EcuM_OnGoOffTwo()</code> abgeschlossen haben und im sicheren Ruhezustand verharren, bevor die Gesamt-MCU stromlos geschaltet oder zurückgesetzt wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ed48926c9397a479", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Sequenzdiagramm (Sequence Diagram) gemäß AUTOSAR-Modellierungsstandard.\n</li><li><strong>Architektur-Ebene:</strong> AUTOSAR Classic Platform (R4.0.3), System Services Layer (BSW).\n</li><li><strong>Funktionaler Zweck:</strong> Spezifikation des Kontrollflusses auf einem Slave-Core während der Phase <code>OffPostOS</code> des ECU State Manager (<code>EcuM</code>). Es definiert das deterministische Minimalverhalten von Sekundärkernen nach der Beendigung des Betriebssystems (<code>ShutdownOS</code>), um eine unkoordinierte Deinitialisierung von BSW-Ressourcen gegenüber dem Master-Core zu unterbinden.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Module &amp; Lebenslinien:</strong>\n<ul class=\"fig-list\"><li><code>«module» EcuM</code>: Instanz des ECU State Managers auf dem jeweiligen Slave-Core mit UML-Dekompositionssymbol (zwei horizontal verbundene Ovale).\n</li><li><code>Integration Code</code>: Integrator-spezifische Code-Ebene bzw. Callout-Schicht außerhalb der standardisierten BSW-Module zur Ausführung hardwarenaher Anpassungen.\n</li><li><code>«module» Os</code>: Operating System (AUTOSAR OS).\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Signaturen:</strong>\n<ul class=\"fig-list\"><li><code>GetCoreID(CoreIdType)</code>: Synchrone Service-Abfrage von <code>EcuM</code> an <code>Os</code>. Entspricht der OS-API <code>CoreIdType GetCoreID(void)</code> zur Bestimmung der logischen Core-ID des ausführenden Slave-Kerns.\n</li><li><code>EcuM_OnGoOffTwo()</code>: Synchroner Callout-Aufruf von <code>EcuM</code> an den <code>Integration Code</code> ohne Übergabeparameter und Rückgabewert (<code>void EcuM_OnGoOffTwo(void)</code>).\n</li></ul>\n</li><li><strong>Strukturelle Beziehungen:</strong> Asymmetrisches Multi-Core-Konzept; <code>EcuM</code> interagiert auf dem Slave-Core in dieser Phase ausschließlich mit dem Betriebssystem (<code>Os</code>) und dem <code>Integration Code</code>, ohne direkte Kopplung an BSW-Treiber (<code>Mcu</code>, <code>Gpt</code> etc.).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Trigger:</strong> Eintritt des Slave-Cores in die <code>OffPostOS</code>-Phase nach erfolgtem OS-Shutdown (<code>ShutdownOS()</code> bzw. Abarbeitung der Shutdown-Hooks).\n</li><li><strong>Ablauf:</strong>\n<ol class=\"fig-list\"><li><code>EcuM</code> setzt auf dem Slave-Core die synchrone Service-Anfrage <code>GetCoreID()</code> an <code>Os</code> ab.\n</li><li><code>Os</code> liefert den Identifikator vom Typ <code>CoreIdType</code> über den Rückgabepfad an <code>EcuM</code> zurück.\n</li><li><code>EcuM</code> ruft synchron den Integrations-Hook <code>EcuM_OnGoOffTwo()</code> im <code>Integration Code</code> auf.\n</li><li>Nach Rückkehr aus <code>EcuM_OnGoOffTwo()</code> endet der Kontrollfluss von <code>EcuM</code> auf dem Slave-Core. Der Kern verharrt im Haltezustand (z. B. Idle-Schleife, Low-Power-Wartemodus wie <code>WFI</code>/<code>WFE</code>), bis der Master-Core die Gesamt-MCU abschaltet oder zurücksetzt.\n</li></ol>\n</li><li><strong>Fehlerbehandlung / Callbacks:</strong> Keine Fehlerbehandlungspfade, Verzweigungen oder Statusrückmeldungen dargestellt.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Asymmetrischer Shutdown-Vertrag:</strong> Treiber-Deinitialisierungen (<code>&lt;Driver&gt;_DeInit</code>), Sleep-Mode-Setzungen (<code>Mcu_SetMode</code>) und System-Resets (<code>Mcu_PerformReset</code>) sind im AUTOSAR-Standard exklusiv dem Master-Core vorbehalten. Slave-Cores manipulieren in <code>OffPostOS</code> keine geteilten Peripherieregister.\n</li><li><strong>Rolle von <code>EcuM_OnGoOffTwo()</code>:</strong> Die Callout-Funktion erlaubt systemspezifische Nachbereitungen auf dem jeweiligen Slave-Core unmittelbar vor dem endgültigen Stillstand (z. B. lokales Abschalten von Core-Clocks, Power-Downs oder Übergang in spezifische Halteinstruktionen). Da das Betriebssystem bereits heruntergefahren ist, dürfen in <code>EcuM_OnGoOffTwo()</code> keine blockierenden OS-Dienste oder Scheduler-abhängigen BSW-APIs aufgerufen werden.\n</li><li><strong>OS-Reentrancy im Post-OS-Zustand:</strong> Die OS-Funktion <code>GetCoreID()</code> muss auch nach inaktivem OS-Scheduler direkt auf prozessoreigene Core-Register zugreifen können, ohne auf Spinlocks oder OS-Verwaltungsstrukturen angewiesen zu sein.\n</li><li><strong>Synchronisationsanforderung für Plattform-Entwickler:</strong> Der Master-Core muss sicherstellen (z. B. über Hardware-Flags oder Inter-Core-Kommunikation), dass alle Slave-Cores <code>EcuM_OnGoOffTwo()</code> abgeschlossen haben und im sicheren Ruhezustand verharren, bevor die Gesamt-MCU stromlos geschaltet oder zurückgesetzt wird.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-b7bb63b523dc3dc1", "to": "FIG-3a37bcd6b0f9e796", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Lebenslinie <code>Integration Code</code> neu hinzugefügt\n</li><li>Synchroner Aufruf <code>EcuM_OnGoOffTwo()</code> von <code>EcuM</code> an <code>Integration Code</code> ergänzt (inklusive Rückkehrpfad)\n</li></ul>"}, {"from": "FIG-3a37bcd6b0f9e796", "to": "FIG-df6d1d779eb7b0f7", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-df6d1d779eb7b0f7", "to": "FIG-cd3d8767072fc514", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cd3d8767072fc514", "to": "FIG-e1989153673aaaf6", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e1989153673aaaf6", "to": "FIG-ed48926c9397a479", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Lebenslinie <code>«module» McOs</code> umbenannt in <code>«module» Os</code>\n</li></ul>"}]};
